<template>
  <t-loading :loading="loading"><t-form class="base-form" :data="formData" :rules="FORM_RULES" label-align="top" :label-width="100" @keydown.enter.prevent @reset="onReset" @submit="onSubmit"><div class="form-basic-container"><div class="form-basic-item"><div class="form-basic-container-title">{{ formData.id ? '处理维修工单' : '新建维修工单' }}</div><p class="form-tip">记录用户的故障描述、处理进度和维修结论。</p><t-row class="row-gap" :gutter="[32, 24]">
    <t-col :xs="12" :lg="6"><t-form-item label="工单编号" name="orderNo"><t-input v-model="formData.orderNo" :maxlength="50" placeholder="请输入工单编号" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="用户 ID" name="userId"><t-input-number v-model="formData.userId" :min="1" placeholder="请输入用户 ID" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="关联站点 ID" name="stationId"><t-input-number v-model="formData.stationId" :min="1" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="故障类型" name="repairType"><t-input v-model="formData.repairType" :maxlength="50" placeholder="例如：无法开柜、电池异常" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="联系电话" name="contactPhone"><t-input v-model="formData.contactPhone" :maxlength="30" placeholder="请输入联系电话" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="工单状态" name="status"><t-select v-model="formData.status"><t-option :value="1" label="待处理" /><t-option :value="2" label="处理中" /><t-option :value="3" label="已完成" /><t-option :value="4" label="已取消" /></t-select></t-form-item></t-col>
    <t-col :span="12"><t-form-item label="问题描述" name="description"><t-textarea v-model="formData.description" :maxlength="2000" placeholder="请尽量描述故障现象、发生时间与位置" /></t-form-item></t-col>
    <t-col :span="12"><t-form-item label="问题图片" name="images"><t-input v-model="formData.images" :maxlength="2000" placeholder="图片地址，多个地址可用逗号或 JSON 数组保存" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="处理人 ID" name="handlerId"><t-input-number v-model="formData.handlerId" :min="1" /></t-form-item></t-col>
    <t-col :xs="12" :lg="6"><t-form-item label="处理时间" name="repairTime"><t-date-picker v-model="formData.repairTime" style="width: 100%" enable-time-picker allow-input clearable /></t-form-item></t-col>
    <t-col :span="12"><t-form-item label="处理说明" name="handleRemark"><t-textarea v-model="formData.handleRemark" :maxlength="2000" placeholder="请输入排查过程和处理结果" /></t-form-item></t-col>
  </t-row></div></div><div class="form-submit-container"><div class="form-submit-sub"><div class="form-submit-left"><t-button theme="primary" class="form-submit-confirm" type="submit">保存工单</t-button><t-button type="reset" class="form-submit-cancel" theme="default" variant="base">重置</t-button></div></div></div></t-form></t-loading>
</template>
<script lang="ts">export default { name: 'repairOrderEdit' };</script>
<script setup lang="ts">
import type { SubmitContext } from 'tdesign-vue-next'; import type { FormRule } from 'tdesign-vue-next'; import { MessagePlugin } from 'tdesign-vue-next'; import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import ApiRepairOrder from '@/api/energy/ApiRepairOrder'; import router from '@/router'; import { closeOrBack } from '@/utils/url-utils';
const route = useRoute(); const loading = ref(true); const formData = ref<any>({ id: null, orderNo: '', userId: null, stationId: null, repairType: '', description: '', images: '', contactPhone: '', status: 1, handlerId: null, handleRemark: '', repairTime: '', createTime: '', updateTime: '' }); const FORM_RULES: Record<string, FormRule[]> = { orderNo: [{ required: true, message: '请输入工单编号', trigger: 'blur' }], userId: [{ required: true, number: true, message: '请输入用户 ID', trigger: 'change' }], repairType: [{ required: true, message: '请输入故障类型', trigger: 'blur' }], status: [{ required: true, number: true, message: '请选择工单状态', trigger: 'change' }] };
function onReset() { if (!formData.value.id) Object.assign(formData.value, { orderNo: '', userId: null, stationId: null, repairType: '', description: '', images: '', contactPhone: '', status: 1, handlerId: null, handleRemark: '', repairTime: '' }); } function onSubmit(context: SubmitContext) { if (context.validateResult !== true) return; ApiRepairOrder.edit({ data: formData.value, success: () => { MessagePlugin.success('工单已保存'); closeOrBack(route, router); } }); } onMounted(() => { const { id } = route.query; if (!id) { loading.value = false; return; } ApiRepairOrder.detail({ id, success: (res: any) => { formData.value = { ...formData.value, ...res }; loading.value = false; }, fail: () => { loading.value = false; } }); });
</script>
<style lang="less" scoped>.form-tip { margin: -4px 0 20px; color: var(--td-text-color-secondary); }</style>
